INSERT INTO zhishi_notices (id, real, source, publish_date, title, event, audience, deadline, countdown, materials, entry, confidence, priority, points, digest_one, digest_points, raw, url, site, unit, src_generated_at) VALUES ('ahau-022', TRUE, '经济管理学院', '2025-11-03', '经济管理学院纪委召开工作会本网讯 10月31日上午，经济管理学院纪委在经管楼304会议室召开工作会。院纪委委员、教工党支', '校内通知', NULL, NULL, NULL, NULL, NULL, 0.5, 'medium', '[{"text": "本网讯 10月31日上午，经济管理学院纪委在经管楼304会议室召开工作会", "quote": "本网讯 10月31日上午，经济管理学院纪委在经管楼304会议室召开工作会"}]'::jsonb, '校内通知：经济管理学院纪委召开工作会本网讯 10月31日上午，经济管理学院纪委在经管楼30', '[{"text": "本网讯 10月31日上午，经济管理学院纪委在经管楼304会议室召开工作会", "quote": "本网讯 10月31日上午，经济管理学院纪委在经管楼304会议室召开工作会"}]'::jsonb, '本网讯 10月31日上午，经济管理学院纪委在经管楼304会议室召开工作会。院纪委委员、教工党支部纪检委员参加会议，会议由学院党委副书记、纪委书记周涛主持。 会议集中学习了《中国共产党第二十届中央委员会第四次全体会议公报》、习近平总书记在中共中央政治局第二十一次集体学习时的重要讲话精神，学习了中共中央政治局常委、中央纪委书记李希在中央纪委国家监委传达学习党的二十届四中全会精神会议上的讲话精神。 会议强调，要把学习贯彻好党的二十届四中全会精神作为当前和今后一个时期的重大政治任务，要在“深学细悟”上下功夫，推动学院纪委工', 'https://jgxy.ahau.edu.cn/info/1101/21686.htm', '经济管理学院 · 工作动态', 'jgxy', '2026-11-04 13:33:17') ON CONFLICT (id) DO UPDATE SET source=EXCLUDED.source, publish_date=EXCLUDED.publish_date, title=EXCLUDED.title, event=EXCLUDED.event, deadline=EXCLUDED.deadline, points=EXCLUDED.points, digest_one=EXCLUDED.digest_one, digest_points=EXCLUDED.digest_points, raw=EXCLUDED.raw, url=EXCLUDED.url, site=EXCLUDED.site, unit=EXCLUDED.unit, src_generated_at=EXCLUDED.src_generated_at